import sys
from itertools import combinations

def is_non_integer_distance(p1, p2):
    dx = p1[0] - p2[0]
    dy = p1[1] - p2[1]
    dist_squared = dx * dx + dy * dy
    return int(dist_squared**0.5)**2 != dist_squared

def find_beautiful_set(n, m):
    points = [(x, y) for x in range(n + 1) for y in range(m + 1) if x + y > 0]
    max_set = []
    for i in range(len(points), 0, -1):
        for candidate in combinations(points, i):
            if all(is_non_integer_distance(p1, p2) for p1, p2 in combinations(candidate, 2)):
                return candidate
    return max_set

n, m = map(int, sys.stdin.read().strip().split())
beautiful_set = find_beautiful_set(n, m)
print(len(beautiful_set))
for x, y in beautiful_set:
    print(x, y)
